<?php
declare(strict_types=1); require dirname(__DIR__,2).'/bootstrap.php';
use App\Core\Auth;use App\Core\Csrf;use App\Core\Database;use App\Services\SchemaUpdater;
Auth::requirePermission('registrations.manage');$pdo=Database::connection();$error='';$notice='';
try{if($_SERVER['REQUEST_METHOD']==='POST'){if(!Csrf::verify($_POST['_csrf']??null))throw new RuntimeException('Invalid security token.');$a=$_POST['action']??'';
 if($a==='save_event'){$id=(int)($_POST['id']??0);$name=trim((string)$_POST['name']);if($name==='')throw new RuntimeException('Event name is required.');$slug=trim((string)$_POST['slug']);if($slug==='')$slug=strtolower(trim(preg_replace('/[^a-z0-9]+/i','-',$name),'-')).'-'.date('Ymd');$data=['name'=>$name,'slug'=>$slug,'event_date'=>$_POST['event_date']?:null,'location'=>trim((string)$_POST['location']),'venue'=>trim((string)$_POST['venue']),'description'=>trim((string)$_POST['description']),'registration_opens_at'=>$_POST['registration_opens_at']?:null,'registration_closes_at'=>$_POST['registration_closes_at']?:null,'payment_instructions'=>trim((string)$_POST['payment_instructions']),'terms_conditions'=>trim((string)$_POST['terms_conditions']),'event_mode'=>$_POST['event_mode'],'status'=>$_POST['status']];
  if($id){$data['id']=$id;$pdo->prepare('UPDATE bdc_events SET name=:name,slug=:slug,event_date=:event_date,location=:location,venue=:venue,description=:description,registration_opens_at=:registration_opens_at,registration_closes_at=:registration_closes_at,payment_instructions=:payment_instructions,terms_conditions=:terms_conditions,event_mode=:event_mode,status=:status WHERE id=:id')->execute($data);}else{$pdo->prepare('INSERT INTO bdc_events(name,normalised_name,slug,event_date,location,venue,description,registration_opens_at,registration_closes_at,payment_instructions,terms_conditions,event_mode,status) VALUES(:name,LOWER(:name),:slug,:event_date,:location,:venue,:description,:registration_opens_at,:registration_closes_at,:payment_instructions,:terms_conditions,:event_mode,:status)')->execute($data);$id=(int)$pdo->lastInsertId();}$notice='Event saved.';$_GET['edit']=$id;
 }
 if($a==='add_ticket'){$event=(int)$_POST['event_id'];$pdo->prepare('INSERT INTO bdc_event_ticket_types(event_id,name,description,price,currency,capacity,includes_workshop,includes_social,includes_jack_jill,status) VALUES(:event,:name,:description,:price,:currency,NULLIF(:capacity,0),:workshop,:social,:jj,:status)')->execute(['event'=>$event,'name'=>trim((string)$_POST['name']),'description'=>trim((string)$_POST['description']),'price'=>(float)$_POST['price'],'currency'=>strtoupper((string)$_POST['currency']),'capacity'=>(int)$_POST['capacity'],'workshop'=>isset($_POST['includes_workshop'])?1:0,'social'=>isset($_POST['includes_social'])?1:0,'jj'=>isset($_POST['includes_jack_jill'])?1:0,'status'=>$_POST['status']]);$notice='Ticket added.';$_GET['edit']=$event;}
 if($a==='delete_ticket'){$pdo->prepare('DELETE FROM bdc_event_ticket_types WHERE id=:id')->execute(['id'=>(int)$_POST['id']]);$notice='Ticket deleted.';$_GET['edit']=(int)$_POST['event_id'];}
 if($a==='copy_event'){
  $sourceId=(int)($_POST['event_id']??0);if($sourceId<1)throw new RuntimeException('Invalid event selected.');
  $s=$pdo->prepare('SELECT * FROM bdc_events WHERE id=:id');$s->execute(['id'=>$sourceId]);$source=$s->fetch();if(!$source)throw new RuntimeException('Event not found.');
  $baseName='Copy of '.$source['name'];$slugBase=strtolower(trim(preg_replace('/[^a-z0-9]+/i','-',$baseName),'-'));$slug=$slugBase.'-'.date('YmdHis');
  $pdo->beginTransaction();
  $pdo->prepare('INSERT INTO bdc_events(name,normalised_name,slug,event_date,location,venue,description,registration_opens_at,registration_closes_at,payment_instructions,terms_conditions,event_mode,status) VALUES(:name,LOWER(:name),:slug,NULL,:location,:venue,:description,NULL,NULL,:payment_instructions,:terms_conditions,:event_mode,:status)')->execute(['name'=>$baseName,'slug'=>$slug,'location'=>$source['location'],'venue'=>$source['venue'],'description'=>$source['description'],'payment_instructions'=>$source['payment_instructions'],'terms_conditions'=>$source['terms_conditions'],'event_mode'=>$source['event_mode'],'status'=>'draft']);
  $newId=(int)$pdo->lastInsertId();
  $pdo->prepare('INSERT INTO bdc_event_ticket_types(event_id,name,description,price,currency,capacity,sales_start_at,sales_end_at,includes_workshop,includes_social,includes_jack_jill,status,sort_order) SELECT :new_id,name,description,price,currency,capacity,NULL,NULL,includes_workshop,includes_social,includes_jack_jill,status,sort_order FROM bdc_event_ticket_types WHERE event_id=:source_id')->execute(['new_id'=>$newId,'source_id'=>$sourceId]);
  $pdo->commit();$notice='Event copied. Update the event name, date and registration dates before publishing.';$_GET['edit']=$newId;
 }
}}catch(Throwable $e){if($pdo->inTransaction())$pdo->rollBack();$error=$e->getMessage();}
$events=$pdo->query('SELECT e.*,(SELECT COUNT(*) FROM bdc_event_ticket_types t WHERE t.event_id=e.id) ticket_count,(SELECT COUNT(*) FROM bdc_event_registrations r WHERE r.event_id=e.id) registration_count FROM bdc_events e ORDER BY event_date DESC,id DESC')->fetchAll();$editId=(int)($_GET['edit']??0);$edit=null;$tickets=[];if($editId){$s=$pdo->prepare('SELECT * FROM bdc_events WHERE id=:id');$s->execute(['id'=>$editId]);$edit=$s->fetch();$s=$pdo->prepare('SELECT * FROM bdc_event_ticket_types WHERE event_id=:id ORDER BY sort_order,id');$s->execute(['id'=>$editId]);$tickets=$s->fetchAll();}
?><!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Events | BDC Admin</title><link href="https://cdn.jsdelivr.net/npm/bootstrap@5.3.3/dist/css/bootstrap.min.css" rel="stylesheet"></head><body class="bg-light"><nav class="navbar navbar-dark bg-dark"><div class="container-fluid"><a class="navbar-brand" href="../">BDC Admin</a><a class="btn btn-outline-light btn-sm" href="../registrations/">Registrations</a></div></nav><main class="container py-4" style="max-width:1250px"><div class="d-flex justify-content-between align-items-center"><h1 class="h3">Events & Tickets</h1><div class="d-flex gap-2"><a class="btn btn-outline-danger" href="merge.php">Merge Duplicate Events</a><a class="btn btn-dark" href="?edit=0">New Event</a></div></div><?php if($error):?><div class="alert alert-danger"><?=e($error)?></div><?php endif;?><?php if($notice):?><div class="alert alert-success"><?=e($notice)?></div><?php endif;?><div class="row g-4 mt-1"><div class="col-lg-7"><div class="card shadow-sm border-0"><div class="card-body"><h2 class="h5"><?=$edit?'Edit event':'Create event'?></h2><form method="post" class="row g-3"><?=Csrf::field()?><input type="hidden" name="action" value="save_event"><input type="hidden" name="id" value="<?=e((string)($edit['id']??0))?>"><div class="col-md-8"><label class="form-label">Event name</label><input class="form-control" name="name" required value="<?=e($edit['name']??'')?>"></div><div class="col-md-4"><label class="form-label">Date</label><input type="date" class="form-control" name="event_date" value="<?=e($edit['event_date']??'')?>"></div><div class="col-md-6"><label class="form-label">Slug</label><input class="form-control" name="slug" value="<?=e($edit['slug']??'')?>"></div><div class="col-md-3"><label class="form-label">Mode</label><select class="form-select" name="event_mode"><option value="bdc">BDC</option><option value="independent" <?=($edit['event_mode']??'')==='independent'?'selected':''?>>Independent</option></select></div><div class="col-md-3"><label class="form-label">Status</label><select class="form-select" name="status"><?php foreach(['draft','published','completed','cancelled'] as $v):?><option <?=($edit['status']??'draft')===$v?'selected':''?>><?=$v?></option><?php endforeach;?></select></div><div class="col-md-6"><label class="form-label">Location</label><input class="form-control" name="location" value="<?=e($edit['location']??'')?>"></div><div class="col-md-6"><label class="form-label">Venue</label><input class="form-control" name="venue" value="<?=e($edit['venue']??'')?>"></div><div class="col-12"><label class="form-label">Description</label><textarea class="form-control" rows="4" name="description"><?=e($edit['description']??'')?></textarea></div><div class="col-md-6"><label class="form-label">Registration opens</label><input type="datetime-local" class="form-control" name="registration_opens_at" value="<?=e(isset($edit['registration_opens_at'])?str_replace(' ','T',substr((string)$edit['registration_opens_at'],0,16)):'')?>"></div><div class="col-md-6"><label class="form-label">Registration closes</label><input type="datetime-local" class="form-control" name="registration_closes_at" value="<?=e(isset($edit['registration_closes_at'])?str_replace(' ','T',substr((string)$edit['registration_closes_at'],0,16)):'')?>"></div><div class="col-12"><label class="form-label">Payment instructions</label><textarea class="form-control" rows="4" name="payment_instructions"><?=e($edit['payment_instructions']??'')?></textarea></div><div class="col-12"><label class="form-label">Terms & conditions</label><textarea class="form-control" rows="4" name="terms_conditions"><?=e($edit['terms_conditions']??'')?></textarea></div><div class="col-12"><button class="btn btn-dark">Save event</button><?php if($edit):?> <a class="btn btn-outline-primary" target="_blank" href="../../event-registration/?event=<?=$edit['id']?>">Open registration form</a><?php endif;?></div></form><?php if($edit):?><form method="post" class="mt-2" onsubmit="return confirm('Create a new draft copy of this event and all its tickets?')"><?=Csrf::field()?><input type="hidden" name="action" value="copy_event"><input type="hidden" name="event_id" value="<?=$edit['id']?>"><button class="btn btn-outline-secondary">Copy event with tickets</button></form><?php endif;?></div></div><?php if($edit):?><div class="card shadow-sm border-0 mt-4"><div class="card-body"><h2 class="h5">Add ticket/pass</h2><form method="post" class="row g-2"><?=Csrf::field()?><input type="hidden" name="action" value="add_ticket"><input type="hidden" name="event_id" value="<?=$edit['id']?>"><div class="col-md-4"><input class="form-control" name="name" placeholder="Ticket name" required></div><div class="col-md-2"><input class="form-control" name="price" type="number" step="0.01" placeholder="Price" required></div><div class="col-md-2"><input class="form-control" name="currency" value="SGD"></div><div class="col-md-2"><input class="form-control" name="capacity" type="number" placeholder="Capacity"></div><div class="col-md-2"><select class="form-select" name="status"><option>active</option><option>inactive</option></select></div><div class="col-12"><input class="form-control" name="description" placeholder="Description"></div><div class="col-12"><label class="me-3"><input type="checkbox" name="includes_workshop"> Workshop</label><label class="me-3"><input type="checkbox" name="includes_social"> Social</label><label><input type="checkbox" name="includes_jack_jill"> Jack & Jill</label></div><div class="col-12"><button class="btn btn-primary">Add ticket</button></div></form><hr><?php foreach($tickets as $t):?><div class="d-flex justify-content-between border rounded p-2 mb-2"><div><strong><?=e($t['name'])?></strong> <?=e($t['currency'])?> <?=number_format((float)$t['price'],2)?> <span class="badge text-bg-secondary"><?=e($t['status'])?></span><div class="small text-muted"><?= $t['includes_jack_jill']?'Includes Jack & Jill':''?></div></div><form method="post" onsubmit="return confirm('Delete ticket?')"><?=Csrf::field()?><input type="hidden" name="action" value="delete_ticket"><input type="hidden" name="id" value="<?=$t['id']?>"><input type="hidden" name="event_id" value="<?=$edit['id']?>"><button class="btn btn-sm btn-outline-danger">Delete</button></form></div><?php endforeach;?></div></div><?php endif;?></div><div class="col-lg-5"><div class="card shadow-sm border-0"><div class="card-body"><h2 class="h5">Existing events</h2><?php foreach($events as $ev):?><div class="border rounded p-3 mb-2"><a class="d-block text-decoration-none" href="?edit=<?=$ev['id']?>"><strong><?=e($ev['name'])?></strong><div class="small text-muted"><?=e((string)$ev['event_date'])?> · <?=e($ev['status'])?> · <?=$ev['ticket_count']?> tickets · <?=$ev['registration_count']?> registrations</div></a><form method="post" class="mt-2" onsubmit="return confirm('Copy this event and all ticket types into a new draft event?')"><?=Csrf::field()?><input type="hidden" name="action" value="copy_event"><input type="hidden" name="event_id" value="<?=$ev['id']?>"><button class="btn btn-sm btn-outline-secondary">Copy</button></form></div><?php endforeach;?></div></div></div></div></main></body></html>
